function refreshMeshes() { state.meshes.forEach((m) => scene.remove(m)); state.meshes = []; (state.session.objects || []).forEach((o) => { const m = buildMesh(o); if (m) state.meshes.push(m); }); refreshGroupOptions(); }
function resolveObj(s) { let n = s; while (n) { if (n.userData && n.userData.obj) return { obj: n.userData.obj, mesh: n }; n = n.parent; } return null; }
let hoverBox = null;
function updateHoverBox(mesh) { if (!hoverBox) { hoverBox = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1)), new THREE.LineBasicMaterial({ color: 0x00ff88 })); scene.add(hoverBox); } if (!mesh) { hoverBox.visible = false; return; } const b = new THREE.Box3().setFromObject(mesh); const sz = b.getSize(new THREE.Vector3()), ct = b.getCenter(new THREE.Vector3()); hoverBox.scale.set(Math.max(sz.x, 0.1), Math.max(sz.y, 0.1), Math.max(sz.z, 0.1)); hoverBox.position.copy(ct); hoverBox.visible = true; }
function setHover(start) { const r = start ? resolveObj(start) : null, mesh = r ? r.mesh : null; if (state.hovered === mesh) return; state.hovered = mesh; updateHoverBox(mesh); const tip = document.getElementById("label-tooltip"); if (mesh) { if (r.obj.type === "label" || r.obj.type === "artwork") { tip.textContent = r.obj.text ? "“" + r.obj.text + "”" : (r.obj.type === "artwork" ? "Artwork — click to view" : ""); tip.style.display = tip.textContent ? "block" : "none"; } else tip.style.display = "none"; } else tip.style.display = "none"; updateHint(); }
function floorPoint(nx, ny) { raycaster.setFromCamera(new THREE.Vector2(nx, ny), camera); const h = raycaster.intersectObject(floor); return h.length ? h[0].point : null; }
function hitObjects(nx, ny) { raycaster.setFromCamera(new THREE.Vector2(nx, ny), camera); return raycaster.intersectObjects(state.meshes, true); }
function cellOf(x, y, z) { return [Math.floor(x / BS), Math.floor(y / BS), Math.floor(z / BS)]; }
function cellCenter(cx, cy, cz) { return [(cx + 0.5) * BS, (cy + 0.5) * BS, (cz + 0.5) * BS]; }
