function currentPermForTool(t) { if (state.canEdit) return true; if (!state.user) return false; if (t === "block") return state.clientPerms.canPlaceWalls; if (t === "case" || t === "floor" || t === "light" || t === "furniture" || t === "barrier") return state.clientPerms.canPlaceDecor || state.clientPerms.canPlaceWalls; if (t === "label") return state.clientPerms.canPlaceLabels; if (t === "artwork") return state.clientPerms.canPlaceArtworks; if (t === "delete") return state.clientPerms.canDelete; if (t === "move") return state.clientPerms.canPlaceWalls || state.clientPerms.canPlaceDecor; return false; }
function placeObject(obj) { return api("/api/sessions/" + state.session.id + "/objects", { method: "POST", body: JSON.stringify(obj) }).then((saved) => { const m = buildMesh(saved); if (m) state.meshes.push(m); state.session.objects.push(saved); flash(m); toast("Placed " + ({ block: "block", artwork: "artwork", label: "label", case: "display case", light: "light" }[obj.type] || obj.type) + " · saved"); return saved; }).catch((e) => toast(e.message)); }
function deleteObject(obj, mesh) { return api("/api/sessions/" + state.session.id + "/objects/" + obj.id, { method: "DELETE" }).then(() => { scene.remove(mesh); state.meshes = state.meshes.filter((m) => m !== mesh); state.session.objects = state.session.objects.filter((o) => o.id !== obj.id); toast("Deleted · saved"); }).catch((e) => toast(e.message)); }
