  if (state.tool === "browse") { const h = hitObjects(nx, ny); if (h.length) { const r = resolveObj(h[0].object); if (r && r.obj.type === "label") openLabel(r.obj); else if (r && r.obj.type === "artwork") openArt(r.obj); else if (r && r.obj.type === "door") toggleDoor(r.obj); else if (r && r.obj.type === "window") openWindow(r.obj); } return; }
  if (state.tool === "block") { const t = blockTarget(nx, ny); if (!t) { toast("Aim at floor or a block"); return; } const cc = cellCenter.apply(null, t.cell); return placeObject({ type: "block", pos: cc, rot: 0, scale: [1, 1, 1], mat: matKey, text: "", image: null }); }
  if (state.tool === "move") { if (moveObj) { const np = moveObj.__np, nr = moveObj.__nr; if (np) { api("/api/sessions/" + state.session.id + "/objects/" + moveObj.id, { method: "PUT", body: JSON.stringify({ pos: np, rot: nr != null ? nr : moveObj.rot }) }).catch((e) => toast(e.message)); moveObj.pos = np; if (nr != null) moveObj.rot = nr; const mm = state.meshes.find((x) => x.userData.obj === moveObj); if (mm) mm.position.set(np[0], moveObj.pos[1] || np[1] || 0, np[2]); toast("Moved · saved"); } moveObj = null; return; } const h = hitObjects(nx, ny); if (h.length) { const r = resolveObj(h[0].object); if (r) { moveObj = r.obj; toast("Selected — aim at a new spot and press E to drop it"); } } return; }
