function makeFloorTexture(pattern, color) { const cv = document.createElement("canvas"); cv.width = cv.height = 256; const c = cv.getContext("2d"); const col = color || "#8a5a2a"; function shade(hex, amt) { const n = parseInt(hex.slice(1), 16); let r = (n >> 16) + amt, g = ((n >> 8) & 255) + amt, b = (n & 255) + amt; r = Math.max(0, Math.min(255, r)); g = Math.max(0, Math.min(255, g)); b = Math.max(0, Math.min(255, b)); return "rgb(" + r + "," + g + "," + b + ")"; } if (pattern === "check") { for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) { c.fillStyle = ((x + y) % 2) ? "#e9e5df" : "#b7b0a7"; c.fillRect(x * 32, y * 32, 32, 32); } } else if (pattern === "marble") { c.fillStyle = "#f2f0ec"; c.fillRect(0, 0, 256, 256); c.strokeStyle = "rgba(130,130,145,.32)"; c.lineWidth = 1.3; for (let i = 0; i < 9; i++) { c.beginPath(); let x = Math.random() * 256; c.moveTo(x, 0); for (let y = 0; y <= 256; y += 16) { x += (Math.random() * 2 - 1) * 22; c.lineTo(x, y); } c.stroke(); } } else if (pattern === "tile") { c.fillStyle = shade(col, 30); c.fillRect(0, 0, 256, 256); c.strokeStyle = shade(col, -60); c.lineWidth = 3; for (let i = 0; i <= 8; i++) { c.beginPath(); c.moveTo(i * 32, 0); c.lineTo(i * 32, 256); c.moveTo(0, i * 32); c.lineTo(256, i * 32); c.stroke(); } } else if (pattern === "stone") { c.fillStyle = "#8f8d88"; c.fillRect(0, 0, 256, 256); c.strokeStyle = "rgba(0,0,0,.35)"; c.lineWidth = 2; for (let y = 0; y < 8; y++) { const off = (y % 2) * 30; for (let x = -1; x < 5; x++) c.strokeRect(x * 64 + off, y * 32, 64, 32); } } else if (pattern === "grass") { c.fillStyle = "#4f7d38"; c.fillRect(0, 0, 256, 256); for (let i = 0; i < 900; i++) { c.fillStyle = "rgba(" + (30 + Math.random() * 60 | 0) + "," + (110 + Math.random() * 80 | 0) + "," + (40 + Math.random() * 40 | 0) + ",.5)"; c.fillRect(Math.random() * 256, Math.random() * 256, 3, 3); } } else if (pattern === "concrete") { c.fillStyle = "#9b9b9b"; c.fillRect(0, 0, 256, 256); for (let i = 0; i < 600; i++) { c.fillStyle = "rgba(0,0,0," + (Math.random() * 0.2) + ")"; c.fillRect(Math.random() * 256, Math.random() * 256, 2, 2); } } else if (pattern === "wood") { for (let y = 0; y < 8; y++) { c.fillStyle = shade(col, (y % 2) ? 14 : 0); c.fillRect(0, y * 32, 256, 32); c.fillStyle = "rgba(0,0,0,.3)"; c.fillRect(0, y * 32, 256, 2); for (let i = 0; i < 6; i++) { c.fillStyle = "rgba(0,0,0,.09)"; c.fillRect(Math.random() * 256, y * 32 + 4 + Math.random() * 26, 40 + Math.random() * 90, 1); } } } else { c.fillStyle = col; c.fillRect(0, 0, 256, 256); } const tex = new THREE.CanvasTexture(cv); tex.wrapS = tex.wrapT = THREE.RepeatWrapping; tex.repeat.set(30, 30); return tex; }
function applyFloor(f) { f = f || (state.session && state.session.floor) || { pattern: "wood", color: "#8a5a2a", image: null }; if (state.session) state.session.floor = f; const key = (f.image ? "i" + f.image : "p" + f.pattern + f.color); if (floorTexKey === key) return; floorTexKey = key; if (f.image) new THREE.TextureLoader().load(f.image, (t) => { t.colorSpace = THREE.sRGBEncoding; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(30, 30); floor.material.map = t; floor.material.needsUpdate = true; }); else { floor.material.map = makeFloorTexture(f.pattern, f.color); floor.material.needsUpdate = true; } }
function applyTime(t) { const h = t == null ? 12 : t; const day = Math.max(0, Math.sin((h - 6) / 12 * Math.PI)); const dusk = 1 - day; sun.intensity = 0.08 + 1.15 * day; sun.position.set(Math.cos(h / 24 * Math.PI * 2) * 45, Math.max(4, day * 48 + 4), Math.sin(h / 24 * Math.PI * 2) * 45); sun.color.copy(new THREE.Color(0xcfe0ff)).lerp(new THREE.Color(0xffe2b0), dusk); amb.intensity = 0.12 + 0.55 * day; hemi.intensity = 0.12 + 0.55 * day; const sky = new THREE.Color(0x070b1a).lerp(new THREE.Color(0x4d7fd6), day); scene.background.copy(sky); scene.fog.color.copy(sky); }
