const TOOLBTN = [["browse", "Walk/Browse", "WASD"], ["block", "Block", "2"], ["case", "Case", "3"], ["light", "Light", "4"], ["furniture", "Furniture", "5"], ["barrier", "Barrier", "6"], ["artwork", "Artwork", "7"], ["label", "Label", "8"], ["delete", "Delete", "9"], ["move", "Move", "0"], ["floor", "Floor", ""], ["time", "Light/Ceil", ""]];
