const FURN_TYPES = { chair: ["simple", "modern"], table: ["rect", "round"], rug: ["rect", "round"], projector: [], door: ["hinged", "double", "sliding", "folding"], window: ["fixed", "louver", "awning"] };
function renderToolbar() { const tb = document.getElementById("toolbar"); tb.innerHTML = ""; TOOLBTN.forEach(([id, name, k]) => { let ok = currentPermForTool(id); if (id === "floor" || id === "time") ok = state.canEdit; if (id !== "browse" && !ok) return; const b = document.createElement("button"); b.className = "tool" + (state.tool === id ? " on" : ""); b.innerHTML = name + '<span class="k">' + k + "</span>"; b.addEventListener("click", () => setTool(id)); tb.appendChild(b); }); tb.classList.remove("hidden"); }
