function updateHint() { const el = document.getElementById("hp-context"); if (!el) return; const OBJ_NAME = { block: "Block", artwork: "Artwork", label: "Label", case: "Display case", light: "Light", wall: "Wall", door: "Door", window: "Window", pedestal: "Pedestal", chair: "Chair", table: "Table", rug: "Rug", projector: "Projector", belt: "Belt", barricade: "Barricade", waterbarrier: "Water barrier", sign: "Sign", vista: "Tour stop" }; const r = state.hovered ? resolveObj(state.hovered) : null; let txt = ""; if (r) { const o = r.obj; txt = (OBJ_NAME[o.type] || "Object") + (o.creatorName ? " · " + o.creatorName : "") + " · " + (state.tool === "delete" ? "aim + E to delete" : state.tool === "move" ? "click to select" : "F use / click"); } else { const map = { artwork: state.curArt ? "Artwork ready — aim at a wall face, press E" : "Artwork: choose a JPG first", label: "Label: aim at a wall, press E", block: "Block: aim at floor / block, press E", case: "Case: aim at the floor / wall", light: "Light: aim at wall / ceiling / floor", furniture: "Furniture: pick in panel, aim at floor / wall", barrier: "Barrier: aim at the floor", move: "Move: click an object, aim, press E to drop", delete: "Delete: aim at an object, press E" }; txt = map[state.tool] || ""; } el.textContent = txt; el.classList.toggle("show", !!txt); el.title = txt; }

