async function openSession(id) {
  try {
    const data = await api("/api/sessions/" + id); if (!data) throw new Error("Load failed");
    state.session = data; state.canEdit = !!data.canEdit;
    const p = data.perms || {}; state.clientPerms = { canPlaceWalls: !!p.canPlaceWalls, canPlaceDecor: !!p.canPlaceDecor, canPlaceLabels: !!p.canPlaceLabels, canPlaceArtworks: !!p.canPlaceArtworks, canDelete: !!p.canDelete };
    document.getElementById("session-title").textContent = data.title;
    document.getElementById("home").classList.add("hidden");
    refreshMeshes(); buildShell(); applyFloor(data.floor); applyTime(data.time);
    closeModal("sessions-modal");
    if (state.user) startPresence();
    syncUI(); document.getElementById("crosshair").classList.remove("hidden");
    stopSessionTimers(); startSessionTimers(); updateHint();
  } catch (e) { toast(e.message); }
}
