  document.getElementById("art-review-show").innerHTML = obj.review ? ('<span class="score">Score ' + esc(obj.review.score) + " / 100</span>" + (obj.review.comment ? " — " + esc(obj.review.comment) : "")) : "";
  const can = state.canEdit;
