document.getElementById("btn-label-save").addEventListener("click", async () => { if (!state.labelObj) return; try { const o = await api("/api/sessions/" + state.session.id + "/objects/" + state.labelObj.id, { method: "PUT", body: JSON.stringify({ text: document.getElementById("label-text").value }) }); state.labelObj.text = o.text; const m = state.meshes.find((x) => x.userData.obj && x.userData.obj.id === state.labelObj.id); if (m) { m.traverse((mm) => { if (mm.isMesh && mm.material && mm.material.map) { mm.material.map = makeLabelTexture(o.text); mm.material.needsUpdate = true; } }); } toast("Saved"); closeModal("label-modal"); } catch (e) { toast(e.message); } });

let chatTimer = null;
function startSessionTimers() { stopSessionTimers(); if (state.user) { pollChat(); chatTimer = setInterval(pollChat, 3000); } }
function stopSessionTimers() { if (chatTimer) clearInterval(chatTimer); chatTimer = null; }
async function pollChat() { try { const msgs = await api("/api/sessions/" + state.session.id + "/chat"); const c = document.getElementById("chat-msgs"); if (c._last !== msgs.length) { c._last = msgs.length; renderChat(msgs); } } catch (e) {} }
