document.getElementById("btn-chat").addEventListener("click", () => { document.getElementById("chat-wrap").classList.toggle("hidden"); pollChat(); });
function toggleHelp() { const hp = document.getElementById("help"); const min = hp.classList.toggle("min"); document.getElementById("btn-help-toggle").textContent = min ? "+" : "–"; }
document.getElementById("hp-head").addEventListener("click", toggleHelp);
document.getElementById("btn-chat-close").addEventListener("click", () => document.getElementById("chat-wrap").classList.add("hidden"));
async function sendChat() { const t = document.getElementById("chat-text").value.trim(); if (!t) return; try { await api("/api/sessions/" + state.session.id + "/chat", { method: "POST", body: JSON.stringify({ text: t }) }); document.getElementById("chat-text").value = ""; pollChat(); } catch (e) { toast(e.message); } }
