let presTimer = null, markerTimer = null; const markers = new Map();
function startPresence() { stopPresence(); sendPresence(); presTimer = setInterval(sendPresence, 2500); markerTimer = setInterval(pollPresence, 2500); }
function stopPresence() { if (presTimer) clearInterval(presTimer); if (markerTimer) clearInterval(markerTimer); presTimer = markerTimer = null; markers.forEach((m, k) => { scene.remove(m); markers.delete(k); }); }
async function sendPresence() { if (!state.user || !state.session) return; try { await api("/api/sessions/" + state.session.id + "/presence", { method: "POST", body: JSON.stringify({ x: Math.round(camera.position.x), z: Math.round(camera.position.z), color: state.myColor }) }); } catch (e) {} }
async function pollPresence() { try { const act = await api("/api/sessions/" + state.session.id + "/presence"); const ids = new Set(); act.forEach((p) => { if (state.user && p.uid === state.user.id) return; ids.add(p.uid); if (!markers.has(p.uid)) { const m = makeAvatar(p.uid, p.name, p.color); markers.set(p.uid, m); scene.add(m); } const mk = markers.get(p.uid); mk.position.set(p.x, 0, p.z); mk.rotation.y = Math.atan2(camera.position.x - p.x, camera.position.z - p.z); }); markers.forEach((m, k) => { if (!ids.has(k)) { scene.remove(m); markers.delete(k); } }); } catch (e) {} }
function makeAvatar(uid, name, color) { const g = new THREE.Group(); const col = new THREE.Color(color || 0xffffff); const leg = new THREE.MeshStandardMaterial({ color: 0x33333d }); const skin = new THREE.MeshStandardMaterial({ color: 0xd9a678 }); const l1 = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.55, 0.16), leg); l1.position.set(-0.09, 0.28, 0); const l2 = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.55, 0.16), leg); l2.position.set(0.09, 0.28, 0); const torso = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.6, 0.24), new THREE.MeshStandardMaterial({ color: col })); torso.position.y = 0.85; const a1 = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 0.12), leg); a1.position.set(-0.3, 0.9, 0); const a2 = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 0.12), leg); a2.position.set(0.3, 0.9, 0); const head = new THREE.Mesh(new THREE.SphereGeometry(0.19, 16, 16), skin); head.position.y = 1.31; const hair = new THREE.Mesh(new THREE.SphereGeometry(0.2, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: 0x3a2a1a })); hair.position.y = 1.36; const nm = makeNameSprite(name, color); g.add(l1, l2, torso, a1, a2, head, hair, nm); return g; }
function makeNameSprite(name, color) { const cv = document.createElement("canvas"); cv.width = 256; cv.height = 64; const ctx = cv.getContext("2d"); ctx.font = "bold 28px sans-serif"; ctx.textAlign = "center"; ctx.lineWidth = 5; ctx.strokeStyle = "rgba(0,0,0,.85)"; ctx.strokeText(name, 128, 44); ctx.fillStyle = color || "#ffffff"; ctx.fillText(name, 128, 44); const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(cv), depthTest: false, transparent: true })); sp.scale.set(3.6, 0.9, 1); sp.position.y = 2.0; return sp; }

function anyModalOpen() { return document.querySelectorAll(".modal:not(.hidden)").length > 0; }
document.getElementById("scene").addEventListener("mousedown", (e) => { if (e.button !== 0 || anyModalOpen()) return; dragging = true; moved = 0; lastX = e.clientX; lastY = e.clientY; });
window.addEventListener("mousemove", (e) => { if (!dragging) return; const dx = e.clientX - lastX, dy = e.clientY - lastY; moved += Math.abs(dx) + Math.abs(dy); yaw -= dx * 0.005; pitch -= dy * 0.005; pitch = Math.max(-1.5, Math.min(1.5, pitch)); lastX = e.clientX; lastY = e.clientY; });
window.addEventListener("mouseup", (e) => { if (!dragging) return; dragging = false; if (moved > 6 || anyModalOpen()) return; const nx = (e.clientX / innerWidth) * 2 - 1, ny = -(e.clientY / innerHeight) * 2 + 1; if (state.tool === "browse") { const h = hitObjects(nx, ny); if (h.length) { const r = resolveObj(h[0].object); if (r && (r.obj.type === "label" || r.obj.type === "artwork")) { interact(nx, ny); return; } } } else if (state.tool === "delete") { const h = hitObjects(nx, ny); if (h.length) { interact(nx, ny); return; } } else if (["block", "case", "light", "artwork", "label", "furniture", "barrier", "move"].includes(state.tool)) { interact(nx, ny); return; } });
document.addEventListener("keydown", (e) => { if (e.repeat) { keys[e.code] = true; return; } if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA")) return; keys[e.code] = true; if (state.session && !anyModalOpen()) { if (e.code === "KeyE") interact(0, 0); if (e.code === "KeyF") useInteract(); if (e.code === "Delete" || e.code === "Backspace") deleteAim(); if (e.code === "Digit1") setTool("browse"); if (e.code === "Digit2") setTool("block"); if (e.code === "Digit3") setTool("case"); if (e.code === "Digit4") setTool("light"); if (e.code === "Digit5") setTool("furniture"); if (e.code === "Digit6") setTool("barrier"); if (e.code === "Digit7") setTool("artwork"); if (e.code === "Digit8") setTool("label"); if (e.code === "Digit9") setTool("delete"); if (e.code === "Digit0") setTool("move"); if (e.code === "KeyM") setTool("move"); if (e.code === "Space") { const now = Date.now(); if (now - lastSpaceT < 320) camera.position.y = EYE; lastSpaceT = now; } } });
document.addEventListener("keyup", (e) => { keys[e.code] = false; });

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05); camera.rotation.set(pitch, yaw, 0);
  let f = 0, s = 0; if (keys["KeyW"]) f += 1; if (keys["KeyS"]) f -= 1; if (keys["KeyA"]) s -= 1; if (keys["KeyD"]) s += 1;
  const inView = !!(state.session && !anyModalOpen());
  if ((f || s) && inView) { const fw = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw)), rt = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw)); const d = new THREE.Vector3(); d.addScaledVector(fw, f).addScaledVector(rt, s); if (d.lengthSq() > 0) { d.normalize().multiplyScalar(7 * dt); camera.position.add(d); } }
  if (inView) { if (keys["Space"]) camera.position.y += 6 * dt; if (keys["ShiftLeft"] || keys["ShiftRight"]) camera.position.y -= 6 * dt; }
  const ceilY = (state.session && state.session.ceiling && state.session.ceiling.mode !== "none") ? (state.session.ceiling.y || 10) : 90;
  camera.position.y = Math.max(0.4, Math.min(ceilY - 0.25, camera.position.y));
  document.getElementById("crosshair").style.display = inView ? "" : "none";
  showBlockCursor();
  if (state.tool === "move" && moveObj) { const mm = state.meshes.find((x) => x.userData.obj === moveObj); let np = null, nr = moveObj.rot; if (["label", "artwork", "door", "window"].includes(moveObj.type)) { const t = wallTarget(0, 0); if (t) { np = t.pos; nr = t.rot; } } else { const p = floorPoint(0, 0); if (p) { np = [p.x, moveObj.pos[1] != null ? moveObj.pos[1] : 0, p.z]; nr = Math.atan2(camera.position.x - p.x, camera.position.z - p.z); } } if (mm && np) { mm.position.set(np[0], np[1], np[2]); if (nr != null) mm.rotation.y = nr; } moveObj.__np = np; moveObj.__nr = nr; }
  if (inView && state.tool !== "block") { const h = hitObjects(0, 0); setHover(h.length ? h[0].object : null); } else setHover(null);
  renderer.render(scene, camera);
}

async function loadHome() {
  const el = document.getElementById("home-sessions");
  const loginBtn = document.getElementById("home-login");
  if (state.user) loginBtn.style.display = "none"; else loginBtn.style.display = "";
  el.innerHTML = '<div class="empty">Loading…</div>';
  try {
    const data = state.user ? await api("/api/sessions") : await api("/api/public/sessions");
    const title = state.user ? (state.user.role === "teacher" ? "Your galleries — create / manage" : "Galleries you can curate") : "Public galleries";
    if (!data.length) { el.innerHTML = '<div class="empty">' + (state.user ? 'No galleries yet. Use the top "Galleries" button to create / open one.' : "No public galleries yet. Log in as a teacher to create one.") + "</div>"; return; }
    el.innerHTML = "";
    const h = document.createElement("div"); h.className = "home-title"; h.textContent = title; el.appendChild(h);
    data.forEach((s) => { const d = document.createElement("div"); d.className = "mli"; d.innerHTML = '<div class="t"><b>' + esc(s.title) + "</b><span>" + esc(s.description || "") + "</span></div>"; const b = document.createElement("button"); b.textContent = "Enter"; b.addEventListener("click", () => openSession(s.id)); d.appendChild(b); if (state.user && state.user.role === "teacher") { const b2 = document.createElement("button"); b2.textContent = "Manage"; b2.addEventListener("click", () => openAdmin(s.id)); d.appendChild(b2); const b3 = document.createElement("button"); b3.textContent = "New"; b3.addEventListener("click", () => document.getElementById("btn-new-session").click()); d.appendChild(b3); } el.appendChild(d); });
  } catch (e) { el.innerHTML = '<div class="empty">Could not load galleries.</div>'; }
}
document.getElementById("home-login").addEventListener("click", () => openModal("login-modal"));
document.getElementById("btn-home").addEventListener("click", goHome);

async function loadSessions() {
  try {
    const data = state.user ? await api("/api/sessions") : await api("/api/public/sessions");
    const list = document.getElementById("sessions-list"); list.innerHTML = "";
    document.getElementById("btn-new-session").style.display = (state.user && state.user.role === "teacher") ? "" : "none";
    if (!data.length) { list.innerHTML = '<div class="empty">No galleries</div>'; return; }
    data.forEach((s) => { const d = document.createElement("div"); d.className = "mli"; d.innerHTML = '<div class="t"><b>' + esc(s.title) + "</b><span>" + esc(s.description || "") + "</span></div>" + '<span class="badge ' + (s.isPublished ? "on" : "") + '">' + (s.isPublished ? "Published" : "Draft") + "</span>"; const b = document.createElement("button"); b.textContent = "Enter"; b.addEventListener("click", () => openSession(s.id)); d.appendChild(b); if (state.user && state.user.role === "teacher") { const b2 = document.createElement("button"); b2.textContent = "Manage"; b2.addEventListener("click", () => openAdmin(s.id)); d.appendChild(b2); const b3 = document.createElement("button"); b3.textContent = "Share"; b3.addEventListener("click", () => copyShare(s.id)); d.appendChild(b3); } list.appendChild(d); });
  } catch (e) { toast(e.message); }
}
function copyShare(id) { const url = location.origin + "/?session=" + (id || state.session.id); (navigator.clipboard ? navigator.clipboard.writeText(url) : Promise.resolve()).then(() => toast("Link copied: " + url)).catch(() => toast(url)); }
document.getElementById("btn-share").addEventListener("click", () => copyShare(state.session.id));
function saveShot() { renderer.render(scene, camera); const a = document.createElement("a"); const name = (state.session && state.session.title || "gallery").replace(/[^\w\-]+/g, "_"); a.download = name + ".png"; a.href = renderer.domElement.toDataURL("image/png"); document.body.appendChild(a); a.click(); document.body.removeChild(a); toast("Screenshot saved"); }
(function addShotBtn() { const shot = document.createElement("button"); shot.className = "hbtn"; shot.textContent = "Screenshot"; shot.id = "btn-shot"; shot.addEventListener("click", saveShot); document.getElementById("btn-sessions").before(shot); })();

let adminSessionId = null;
async function openAdmin(id) { try { const s = await api("/api/sessions/" + id); adminSessionId = id; document.getElementById("adm-title").value = s.title; document.getElementById("adm-desc").value = s.description || ""; document.getElementById("adm-pub").checked = !!s.isPublished; ["adm-pw", "adm-pd", "adm-pl", "adm-pa", "adm-pdel"].forEach((i) => { document.getElementById(i).checked = false; }); const P = s.perms || {}; document.getElementById("adm-pw").checked = !!P.canPlaceWalls; document.getElementById("adm-pd").checked = !!P.canPlaceDecor; document.getElementById("adm-pl").checked = !!P.canPlaceLabels; document.getElementById("adm-pa").checked = !!P.canPlaceArtworks; document.getElementById("adm-pdel").checked = !!P.canDelete; const studs = await api("/api/students"); const mem = s.members || []; const box = document.getElementById("adm-members"); box.innerHTML = ""; studs.forEach((u) => { const row = document.createElement("label"); row.style.display = "flex"; row.style.alignItems = "center"; row.style.gap = "8px"; row.style.padding = "6px 8px"; const cb = document.createElement("input"); cb.type = "checkbox"; cb.checked = mem.includes(u.id); cb.dataset.id = u.id; row.appendChild(cb); const nm = document.createElement("span"); nm.style.flex = "1"; nm.textContent = u.name + " (" + u.username + ")"; row.appendChild(nm); const gp = document.createElement("input"); gp.type = "text"; gp.placeholder = "Group"; gp.value = u.group || ""; gp.dataset.uid = u.id; gp.style.width = "90px"; row.appendChild(gp); box.appendChild(row); }); openModal("admin-modal"); } catch (e) { toast(e.message); } }
document.getElementById("btn-adm-save").addEventListener("click", async () => { const members = Array.from(document.querySelectorAll("#adm-members input[type=checkbox]:checked")).map((c) => c.dataset.id); const groups = document.querySelectorAll("#adm-members input[type=text]"); try { await api("/api/sessions/" + adminSessionId, { method: "PUT", body: JSON.stringify({ title: document.getElementById("adm-title").value, description: document.getElementById("adm-desc").value, isPublished: document.getElementById("adm-pub").checked, perms: { canPlaceWalls: document.getElementById("adm-pw").checked, canPlaceDecor: document.getElementById("adm-pd").checked, canPlaceLabels: document.getElementById("adm-pl").checked, canPlaceArtworks: document.getElementById("adm-pa").checked, canDelete: document.getElementById("adm-pdel").checked }, members }) }); for (const gp of groups) await api("/api/students/" + gp.dataset.uid + "/group", { method: "POST", body: JSON.stringify({ group: gp.value }) }); toast("Saved"); closeModal("admin-modal"); loadSessions(); } catch (e) { toast(e.message); } });
document.getElementById("btn-adm-delete").addEventListener("click", async () => { if (!confirm("Delete this gallery?")) return; try { await api("/api/sessions/" + adminSessionId, { method: "DELETE" }); toast("Deleted"); closeModal("admin-modal"); loadSessions(); } catch (e) { toast(e.message); } });
document.getElementById("btn-new-session").addEventListener("click", async () => { const t2 = prompt("Gallery title:"); if (!t2) return; try { const s = await api("/api/sessions", { method: "POST", body: JSON.stringify({ title: t2, description: "" }) }); toast("Created: " + s.title); loadSessions(); loadHome(); } catch (e) { toast(e.message); } });

function setAuthUI() { const b = document.getElementById("btn-auth"); if (state.user) b.textContent = state.user.name + " (" + (state.user.role === "teacher" ? "Teacher" : "Student") + ")  Log out"; else b.textContent = "Log in"; }
document.getElementById("btn-auth").addEventListener("click", () => { if (state.user) doLogout(); else openModal("login-modal"); });
async function doLogout() { try { await api("/api/logout", { method: "POST" }); } catch (e) {} localStorage.removeItem("cs_token"); state.token = null; state.user = null; stopPresence(); stopSessionTimers(); setAuthUI(); syncUI(); toast("Logged out"); loadHome(); loadSessions(); }
async function doLogin(u, p) { try { const r = await api("/api/login", { method: "POST", body: JSON.stringify({ username: u, password: p }) }); state.token = r.token; state.user = r.user; localStorage.setItem("cs_token", r.token); closeModal("login-modal"); setAuthUI(); toast("Welcome, " + r.user.name); syncUI(); if (state.session) startPresence(); loadHome(); loadSessions(); } catch (e) { alert(e.message); } }
document.getElementById("btn-login").addEventListener("click", () => doLogin(document.getElementById("lg-user").value, document.getElementById("lg-pass").value));
document.getElementById("lg-pass").addEventListener("keydown", (e) => { if (e.key === "Enter") doLogin(document.getElementById("lg-user").value, document.getElementById("lg-pass").value); });
let rgRole = "student";
function rgToggle() { const keyRow = document.querySelector("#rg-key") ? document.querySelector("#rg-key").closest(".row") : null; if (keyRow) keyRow.style.display = rgRole === "teacher" ? "" : "none"; }
document.getElementById("rg-role-student").addEventListener("click", () => { rgRole = "student"; document.getElementById("rg-role-student").classList.add("on"); document.getElementById("rg-role-teacher").classList.remove("on"); rgToggle(); });
document.getElementById("rg-role-teacher").addEventListener("click", () => { rgRole = "teacher"; document.getElementById("rg-role-teacher").classList.add("on"); document.getElementById("rg-role-student").classList.remove("on"); rgToggle(); });
document.getElementById("tab-login").addEventListener("click", () => { document.getElementById("login-form").classList.remove("hidden"); document.getElementById("register-form").classList.add("hidden"); document.getElementById("tab-login").classList.add("on"); document.getElementById("tab-register").classList.remove("on"); });
document.getElementById("tab-register").addEventListener("click", () => { document.getElementById("register-form").classList.remove("hidden"); document.getElementById("login-form").classList.add("hidden"); document.getElementById("tab-register").classList.add("on"); document.getElementById("tab-login").classList.remove("on"); rgToggle(); });
document.getElementById("btn-register").addEventListener("click", async () => { try { await api("/api/register", { method: "POST", body: JSON.stringify({ username: document.getElementById("rg-user").value, name: document.getElementById("rg-name").value, password: document.getElementById("rg-pass").value, role: rgRole, adminKey: document.getElementById("rg-key").value }) }); toast("Registered — please log in"); document.getElementById("tab-login").click(); } catch (e) { alert(e.message); } });

document.getElementById("btn-profile").addEventListener("click", () => { const p = (state.user && state.user.profile) || {}; document.getElementById("pf-color").value = p.color || "#4a7bd0"; document.getElementById("pf-skin").value = p.skin || "#d9a678"; document.getElementById("pf-hair").value = p.hair || "#3a2a1a"; openModal("profile-modal"); });
document.getElementById("btn-pf-save").addEventListener("click", async () => { try { const r = await api("/api/profile", { method: "POST", body: JSON.stringify({ color: document.getElementById("pf-color").value, skin: document.getElementById("pf-skin").value, hair: document.getElementById("pf-hair").value }) }); state.user.profile = r.profile; closeModal("profile-modal"); toast("Avatar saved"); } catch (e) { toast(e.message); } });
async function loadUsers() { try { const list = await api("/api/users"); const el = document.getElementById("users-list"); el.innerHTML = ""; list.forEach((u) => { const d = document.createElement("div"); d.className = "mli"; d.innerHTML = '<div class="t"><b>' + esc(u.name) + " (" + esc(u.username) + ")</b><span>" + (u.role === "teacher" ? "Teacher" : "Student") + (u.blockedUntil && u.blockedUntil > Date.now() ? " · blocked" : "") + "</span></div>"; if (u.role === "student") { const db = document.createElement("button"); db.textContent = "Delete"; db.addEventListener("click", () => delUser(u.id)); d.appendChild(db); const bl = document.createElement("button"); bl.textContent = "Block"; bl.addEventListener("click", () => blockUser(u.id)); d.appendChild(bl); const gr = document.createElement("button"); gr.textContent = "Grade"; gr.addEventListener("click", () => openStudentGrade(u)); d.appendChild(gr); } el.appendChild(d); }); openModal("users-modal"); } catch (e) { toast(e.message); } }
async function openStudentGrade(u) { try { document.getElementById("grade-title").textContent = "Grading — " + u.name; const ss = await api("/api/sessions"); document.getElementById("grade-body").innerHTML = "<div class='empty'>Loading…</div>"; let rows = ""; const arts = []; for (const s of ss) { const d = await api("/api/sessions/" + s.id); (d.objects || []).forEach((o) => { if (o.creatorName === u.name) arts.push({ s: s.title, o }); }); } document.getElementById("grade-body").innerHTML = arts.length ? "" : "<div class='empty'>No artworks yet.</div>"; arts.forEach(({ s, o }) => { const d = document.createElement("div"); d.className = "mli"; d.innerHTML = '<div class="t"><b>' + esc(o.text || "Artwork") + "</b><span>" + esc(s) + (o.review ? " · <span class='score'>score " + esc(o.review.score) + "/100</span>" : "") + "</span></div>"; const b = document.createElement("button"); b.textContent = o.review ? "Review" : "Score"; b.addEventListener("click", () => { openSessionFromGrade(s, o); }); d.appendChild(b); document.getElementById("grade-body").appendChild(d); }); openModal("grade-modal"); } catch (e) { toast(e.message); } }
function openSessionFromGrade(sessionId, obj) { closeModal("grade-modal"); openSession(sessionId); }
document.getElementById("btn-users").addEventListener("click", loadUsers);
async function delUser(id) { if (!confirm("Delete this student account?")) return; try { await api("/api/users/" + id, { method: "DELETE" }); toast("Account deleted"); loadUsers(); } catch (e) { toast(e.message); } }
async function blockUser(id) { const h = prompt("Block for how many hours? (0 = unblock)"); if (h == null) return; try { await api("/api/users/" + id + "/block", { method: "POST", body: JSON.stringify({ hours: +h || 0 }) }); toast("Updated"); loadUsers(); } catch (e) { toast(e.message); } }
document.getElementById("btn-sessions").addEventListener("click", () => { loadSessions(); document.getElementById("sessions-title").textContent = state.user ? "My galleries / accessible" : "Public galleries"; openModal("sessions-modal"); });
document.getElementById("btn-admin").addEventListener("click", () => { if (state.session) openAdmin(state.session.id); });

async function boot() {
  initScene();
  if (state.token) { try { const r = await api("/api/me"); state.user = r.user; } catch (e) { state.token = null; localStorage.removeItem("cs_token"); } }
  setAuthUI(); loadHome(); renderToolbar();
  const qs = new URLSearchParams(location.search); if (qs.get("session")) { try { const d = await api("/api/public/sessions/" + qs.get("session")); if (d) openSession(d.id); else document.getElementById("home").classList.remove("hidden"); } catch (e) { document.getElementById("home").classList.remove("hidden"); } }
  animate();
}
window.addEventListener("resize", onResize);
boot();
